def lru_ttl_simulate(capacity, ttl, ops):
    from collections import OrderedDict
    cache = OrderedDict()  # key -> (value, write_time); order = recency (LRU first)
    out = []
    for op in ops:
        if op[1] == 'get':
            t, _, key = op
            if key in cache:
                value, wt = cache[key]
                if t - wt >= ttl:
                    del cache[key]
                    out.append(None)
                else:
                    cache.move_to_end(key)
                    out.append(value)
            else:
                out.append(None)
        else:
            t, _, key, value = op
            if key in cache:
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    expired = [k for k, (v, wt) in cache.items() if t - wt >= ttl]
                    for k in expired:
                        del cache[k]
                    while len(cache) >= capacity:
                        cache.popitem(last=False)
                cache[key] = (value, t)
    return out

