def avg_pool1d_divisors(length, kernel, stride, padding, ceil_mode, count_include_pad):
    span = length + 2 * padding - kernel
    if ceil_mode:
        out = -(-span // stride) + 1
        if (out - 1) * stride >= length + padding:
            out -= 1
    else:
        out = span // stride + 1
    divisors = []
    for i in range(out):
        start = i * stride - padding
        end = min(start + kernel, length + padding)
        if count_include_pad:
            divisors.append(end - start)
        else:
            cs = max(start, 0)
            ce = min(end, length)
            divisors.append(ce - cs)
    return divisors

